 async function loadBuiltDashboard(){setBuilding(v=>v?{...v,ready:false,error:''}:v);try{await queryClient.invalidateQueries({queryKey:['snapshot'],refetchType:'none'});await queryClient.fetchQuery({queryKey:['snapshot'],queryFn:adapter.load});setBuilding(v=>v?{...v,ready:true}:v);}catch(e){setBuilding(v=>v?{...v,error:(e as Error).message}:v);}}
