 const [form,setForm]=useState<{kind:Kind;record?:LedgerRecord;initial?:Record<string,unknown>}|null>(null);const [quick,setQuick]=useState(false);const [remove,setRemove]=useState<LedgerRecord|null>(null);const [notice,setNotice]=useState('');const [saveState,setSaveState]=useState<'idle'|'saving'|'saved'|'error'>('idle');
 const {data:s,isPending,isError,error,refetch}=useQuery({queryKey:['snapshot'],queryFn:adapter.load,refetchInterval:15000});const referralQuery=useQuery<ReferralSummary>({queryKey:['referrals',s?.profile.email,s?.profile.plan],queryFn:()=>request('/api/referrals'),enabled:!demoMode&&!!s&&(s.profile.plan!=='Free'||path==='settings'),refetchInterval:15000});const workspaceNavigation=[...navigation.slice(0,-2),...(s?.profile.plan!=='Free'&&referralQuery.data?.rankingActive?[['ranking','Referral ranking',Trophy] as const]:[]),...navigation.slice(-2)];const recordMotion=useRecordMotion(s?.records,fullPath);const dashboardMetrics=useMemo(()=>s?metrics(s.records,month,s.profile.currency,s.profile.timezone,now()):null,[s,month]);
 useEffect(()=>{const show=(event:Event)=>setUpgrade({reason:(event as CustomEvent<{reason:string}>).detail.reason});window.addEventListener('ledger-upgrade-required',show);return()=>window.removeEventListener('ledger-upgrade-required',show);},[]);
 useEffect(()=>{if(!s)return;if(previousPlan.current&&previousPlan.current!==s.profile.plan)setUpgrade(null);previousPlan.current=s.profile.plan;},[s?.profile.plan]);
 useEffect(()=>{
  if(!s||s.profile.plan!=='Free'||path==='plans'||building||form||quick||remove||upgrade||(!demoMode&&!s.profile.onboardingCompletedAt))return;
  const day=localDate(new Date(),s.profile.timezone),key='daily-ledger-upgrade:'+s.profile.email.toLowerCase();
  if(dailySeen.current===key+day)return;
  // ponytail: once per account/browser/day; persist server-side if cross-device impressions matter.
  try{if(localStorage.getItem(key)===day)return;localStorage.setItem(key,day);}catch{/* Session guard still prevents repeated prompts if storage is unavailable. */}
  dailySeen.current=key+day;setUpgrade({daily:true,theme:Array.from(day).reduce((a,c)=>a+c.charCodeAt(0),0)%3,reason:'See what Pro and Lifetime can add to your daily routine.'});
 },[s?.profile.plan,s?.profile.email,path,building,form,quick,remove,upgrade]);
 const access=useQuery({queryKey:['account-access'],queryFn:()=>request('/auth/me'),enabled:!demoMode&&!!s,refetchInterval:15000,refetchOnWindowFocus:true});
 useEffect(()=>{if(!demoMode&&s)void queryClient.invalidateQueries({queryKey:['account-access']});},[fullPath,queryClient,s?.profile.email]);
 useEffect(()=>{if(s&&!demoMode){const selected=new URLSearchParams(window.location.search).get('month');setMonth(selected&&/^\d{4}-(0[1-9]|1[0-2])$/.test(selected)?selected:localDate(new Date(),s.profile.timezone).slice(0,7));}},[s?.profile.email,s?.profile.timezone]);
 const drawerRef=useDrawer(drawer,()=>setDrawer(false),!!s&&(demoMode||!!s.profile.onboardingCompletedAt)&&!building);
 useEffect(()=>{if(!demoMode&&error instanceof ApiError&&error.status===401)router.replace('/login?returnTo='+encodeURIComponent(window.location.pathname+window.location.search));},[error,router]);
 useEffect(()=>{setDrawer(false);const params=new URLSearchParams(window.location.search);setCategory(params.get('category')||'');const selected=params.get('month');if(selected&&/^\d{4}-(0[1-9]|1[0-2])$/.test(selected))setMonth(selected);},[fullPath]);
 useEffect(()=>{if(!notice)return;const t=setTimeout(()=>setNotice(''),4500);return ()=>clearTimeout(t);},[notice]);
 const seenAnnouncements=useRef(new Set<string>());
 useEffect(()=>{if(!s||path!==''||building||(!demoMode&&!s.profile.onboardingCompletedAt))return;const a=recordsOf(s.records,'announcement').filter(r=>!s.dismissed.includes(`${r.id}:${r.data.version}`)&&new Date(r.data.publishAt)<=now()&&new Date(r.data.expiresAt)>now()&&(r.data.audience==='Everyone'||r.data.audience===s.profile.plan)).sort((a,b)=>b.data.priority-a.data.priority)[0];if(!a)return;const key=`${a.id}:${a.data.version}`;if(seenAnnouncements.current.has(key))return;seenAnnouncements.current.add(key);void adapter.readAnnouncement(a.id,a.data.version).catch(()=>seenAnnouncements.current.delete(key));},[s,path,building]);
 const save=useMutation({mutationFn:adapter.save,onMutate:async input=>{
  setSaveState('saving');await queryClient.cancelQueries({queryKey:['snapshot']});
  const previous=queryClient.getQueryData<Snapshot>(['snapshot'])?.records.find(r=>r.id===input.id);
  const optimistic=!!previous||input.kind==='completion';const id=input.id||crypto.randomUUID();
  const optimisticRecord={id,kind:input.kind,version:input.version||1,data:input.kind==='task'?{...(input.data as object),completedAt:(input.data as any).done?now().toISOString():null}:input.data} as LedgerRecord;
  if(optimistic)queryClient.setQueryData<Snapshot>(['snapshot'],snapshot=>snapshot?{...snapshot,records:previous?snapshot.records.map(r=>r.id===id?optimisticRecord:r):[...snapshot.records,optimisticRecord]}:snapshot);
  return {previous,id,optimistic};
 },onSuccess:async(result,_input,context)=>{
  if(context?.optimistic&&result)queryClient.setQueryData<Snapshot>(['snapshot'],snapshot=>snapshot?{...snapshot,records:snapshot.records.map(r=>r.id===context.id?result:r)}:snapshot);
  await queryClient.invalidateQueries({queryKey:['snapshot']});setSaveState('saved');setForm(null);
 },onError:(_error,_input,context)=>{
  if(context?.optimistic)queryClient.setQueryData<Snapshot>(['snapshot'],snapshot=>snapshot?{...snapshot,records:[...snapshot.records.filter(r=>r.id!==context.id),...(context.previous?[context.previous]:[])]}:snapshot);
  setSaveState('error');
 }});
 const deletion=useMutation({mutationFn:(r:LedgerRecord)=>adapter.remove(r.id,r.version),onMutate:async record=>{setSaveState('saving');if(record.kind==='completion'){await queryClient.cancelQueries({queryKey:['snapshot']});queryClient.setQueryData<Snapshot>(['snapshot'],snapshot=>snapshot?{...snapshot,records:snapshot.records.filter(r=>r.id!==record.id)}:snapshot);return record;}},onSuccess:async()=>{await queryClient.invalidateQueries({queryKey:['snapshot']});setRemove(null);setSaveState('saved');},onError:(_error,_record,previous)=>{if(previous)queryClient.setQueryData<Snapshot>(['snapshot'],snapshot=>snapshot?{...snapshot,records:[...snapshot.records.filter(r=>r.id!==previous.id),previous]}:snapshot);setSaveState('error');}});
 function edit(r:LedgerRecord){if(r.kind==='notification'){toggle(r,'read');setNotificationOpen(true);return;}save.reset();setForm({kind:r.kind,record:r});}
 function add(kind:Kind,initial?:Record<string,unknown>){save.reset();setQuick(false);if(s){const key=quotaKinds[kind as keyof typeof quotaKinds];const selectedMonth=String(initial?.date||month).slice(0,7);if(key&&planUsage(s,selectedMonth)[key]>=effectiveLimits(s)[key]){setUpgrade({reason:'Your '+key+' allowance is full. Complete, pause or remove an eligible item, or compare paid plans.'});return;}if(kind==='recurring'&&!plans[s.profile.plan].recurring){setUpgrade({reason:'Repeating transactions are included with Pro and Lifetime.'});return;}}setForm({kind,initial});}
 async function markAllRead(){try{await Promise.all(unread.map(r=>adapter.save({id:r.id,kind:'notification',version:r.version,data:{...r.data,read:true}})));await queryClient.invalidateQueries({queryKey:['snapshot']});}catch(e){setNotice((e as Error).message);}}
 function toggle(r:LedgerRecord,key='done'){save.mutate({...r,data:{...r.data,[key]:!(r.data as any)[key]}});}
 async function completeHabit(h:LedgerRecord<'habit'>,date:string){const existing=recordsOf(s!.records,'completion').find(r=>r.data.habitId===h.id&&r.data.date===date);if(existing)deletion.mutate(existing);else save.mutate({kind:'completion',data:{habitId:h.id,date}});}
 async function dismiss(r:LedgerRecord<'announcement'>){try{await adapter.dismiss(r.id,r.data.version);await refetch();}catch(e){setNotice((e as Error).message);}}
 function exportReport(){if(s&&!plans[s.profile.plan].history&&month!==localDate(now(),s.profile.timezone).slice(0,7)){setUpgrade({reason:'Historical monthly reports require Pro or Lifetime. Full workspace export remains available in Settings.'});return;}if(s)download(csv(fullReportRows(s,month,now())),`daily-ledger-${month}.csv`);}
 const today=s?localDate(now(),s.profile.timezone):'';
